-- READ-ONLY indexed-range screen; 2019 1h-to-<24h gaps, chunk 1; one archive per query.
SELECT gap_id, COUNT(*) row_count, SUM(outTemp IS NOT NULL) outTemp_nonnull, SUM(outTemp=0) outTemp_zero, SUM(outHumidity IS NOT NULL) outHumidity_nonnull, SUM(rain IS NOT NULL) rain_nonnull, SUM(rainRate IS NOT NULL) rainRate_nonnull, SUM(windSpeed IS NOT NULL) windSpeed_nonnull, SUM(windGust IS NOT NULL) windGust_nonnull, SUM(windDir IS NOT NULL) windDir_nonnull, SUM(barometer IS NOT NULL) barometer_nonnull, COUNT(DISTINCT usUnits) distinct_usUnits, COUNT(DISTINCT `interval`) distinct_interval
FROM (SELECT CASE WHEN dateTime>1558259700 AND dateTime<1558341000 THEN '2019:1558259700:1558341000' WHEN dateTime>1559203200 AND dateTime<1559208900 THEN '2019:1559203200:1559208900' WHEN dateTime>1559209500 AND dateTime<1559213700 THEN '2019:1559209500:1559213700' WHEN dateTime>1559219100 AND dateTime<1559223300 THEN '2019:1559219100:1559223300' WHEN dateTime>1572134100 AND dateTime<1572138000 THEN '2019:1572134100:1572138000' END gap_id, a.* FROM `pocasi-loucka.eu_GW1000`.archive a WHERE (dateTime>1558259700 AND dateTime<1558341000) OR (dateTime>1559203200 AND dateTime<1559208900) OR (dateTime>1559209500 AND dateTime<1559213700) OR (dateTime>1559219100 AND dateTime<1559223300) OR (dateTime>1572134100 AND dateTime<1572138000)) hits
GROUP BY gap_id ORDER BY gap_id;
